import urllib.request
import json

url = 'https://api.elsevier.com/content/subject/success'
req = urllib.request.Request(url, headers={
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
    'Accept': 'application/json'
})
try:
    with urllib.request.urlopen(req, timeout=15) as response:
        content = response.read().decode('utf-8')
        data = json.loads(content)

        # Filter subjects containing Health or Life
        for subj in data.get('subject-classifications', {}).get('subject-classification', []):
            desc = subj['description'].lower()
            if 'health' in desc or 'life' in desc or 'bio' in desc:
                print(f"{subj['code']}: {subj['description']}")
except Exception as e:
    print(f"Error: {e}")
EOF

